/** Every photo file the catalog and the home page use (for the integrity test and for a quick `ls`). */
export const photoFilesOf = () => {
	const files = new Set();
	for (const [, , , , image] of CATEGORIES) files.add(image);
	for (const p of APPAREL) {
		files.add(p.image);
		files.add(p.extra);
		for (const file of Object.values(p.colourImages)) files.add(file);
	}
	for (const p of [...ACCESSORIES, ...BUNDLES, MEMBERSHIP]) {
		files.add(p.image);
		for (const file of p.gallery) files.add(file);
	}
	files.add(HOME.cta.image);
	files.add(HOME.look.image);
	files.add(HOME.spotlight.image);
	return [...files].sort();
};
